-- modify "charge_credit_purchases" table
ALTER TABLE "charge_credit_purchases" DROP CONSTRAINT "cost_basis_schema_level_settlement_fields", ADD CONSTRAINT "cost_basis_schema_level_settlement_fields" CHECK ((settlement_type IS NOT NULL) AND ((((settlement_type)::text = 'external'::text) AND (initial_payment_settlement_status IS NOT NULL)) OR (((settlement_type)::text = ANY ((ARRAY['invoice'::character varying, 'promotional'::character varying])::text[])) AND (initial_payment_settlement_status IS NULL)))), DROP CONSTRAINT "schema_level", ADD CONSTRAINT "schema_level" CHECK (schema_level = 2), ALTER COLUMN "settlement" DROP NOT NULL, ALTER COLUMN "schema_level" SET DEFAULT 2;
